function pickFolder(doc2) {
  return new Promise((resolve) => {
    const input = doc2.createElement("input");
    input.type = "file";
    input.setAttribute("webkitdirectory", "");
    input.classList.add("qaudio-hidden");
    input.addEventListener("change", () => {
      const file = input.files?.[0];
      input.remove();
      if (!file) {
        resolve(null);
        return;
      }
      let full = "";
      full = file.path || "";
      const relative = file.webkitRelativePath || "", root = relative.split("/")[0];
      resolve(full && relative ? full.slice(0, full.length - (relative.length - root.length)) : null);
    });
    input.addEventListener("cancel", () => {
      input.remove();
      resolve(null);
    });
    doc2.body.appendChild(input);
    input.click();
  });
}

